	MaxModelSizeMB       int    `json:"max_model_size_mb"`
}

func Default() *Config {
	return &Config{
		Port:                  9090,
		DataDir:               "/app/data",
		ModelStorageDir:       "/app/data/models",
		InferenceTimeoutSec:   30,
		MaxBatchSize:          100,
		LogLevel:              "info",
		WebhookTimeoutSec:     5,
		MetricsRetentionHours: 24,
		MaxModelSizeMB:        500,
	}
}

func Load(path string) (*Config, error) {
	cfg := Default()

	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
			return nil, err
		}
		if err := Save(path, cfg); err != nil {
			return nil, err
		}
		return cfg, nil
	}
	if err != nil {
		return nil, err
	}
	if len(data) > 0 {
		if err := json.Unmarshal(data, cfg); err != nil {
			return nil, err
		}
	}

	if cfg.Port <= 0 {
		cfg.Port = 9090
	}
	if cfg.DataDir == "" {
		cfg.DataDir = "/app/data"
	}
	if cfg.ModelStorageDir == "" {
		cfg.ModelStorageDir = "/app/data/models"
	}
	if cfg.InferenceTimeoutSec <= 0 {
		cfg.InferenceTimeoutSec = 30
	}
	if cfg.MaxBatchSize <= 0 {
		cfg.MaxBatchSize = 100
	}
	if cfg.LogLevel == "" {
		cfg.LogLevel = "info"
	}
	if cfg.WebhookTimeoutSec <= 0 {
		cfg.WebhookTimeoutSec = 5
	}
	if cfg.MetricsRetentionHours <= 0 {
		cfg.MetricsRetentionHours = 24
	}
	if cfg.MaxModelSizeMB <= 0 {
		cfg.MaxModelSizeMB = 500
	}

	return cfg, nil
}

func Save(path string, cfg *Config) error {
	data, err := json.MarshalIndent(cfg, "", "  ")
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}
