package store

import (
    "crypto/rand"
    "encoding/hex"
    "encoding/json"
    "errors"
    "os"
    "path/filepath"
    "sync"
    "time"
)

type User struct {
    ID           string    `json:"id"`
    Username     string    `json:"username"`
    PasswordHash string    `json:"password_hash"`
    Role         string    `json:"role"`
    APIKey       string    `json:"api_key"`
    CreatedAt    time.Time `json:"created_at"`
}

type Lineage struct {
    TrainingDataset string             `json:"training_dataset"`
    ParentModel     string             `json:"parent_model"`
    TrainingMetrics map[string]float64 `json:"training_metrics"`
}

type Version struct {
    Version      string    `json:"version"`
    ReleaseNotes string    `json:"release_notes"`
    BinaryPath   string    `json:"binary_path"`
    Status       string    `json:"status"`
    CreatedAt    time.Time `json:"created_at"`
    Size         int64     `json:"size"`
}

type Model struct {
    ID           string          `json:"id"`
    Name         string          `json:"name"`
    Framework    string          `json:"framework"`
    Description  string          `json:"description"`
    Author       string          `json:"author"`
    CreatedAt    time.Time       `json:"created_at"`
    InputSchema  json.RawMessage `json:"input_schema"`
    OutputSchema json.RawMessage `json:"output_schema"`
    Labels       map[string]string `json:"labels"`
    Lineage      Lineage         `json:"lineage"`
    Versions     []*Version      `json:"versions"`
}

type Webhook struct {
    ID        string    `json:"id"`
    URL       string    `json:"url"`
    Events    []string  `json:"events"`
    CreatedAt time.Time `json:"created_at"`
}

type AuditEntry struct {
    Timestamp     time.Time `json:"timestamp"`
    User          string    `json:"user"`
    Action        string    `json:"action"`
    ResourceType  string    `json:"resource_type"`
    ResourceID    string    `json:"resource_id"`
    Details       string    `json:"details"`
    SourceIP      string    `json:"source_ip"`
}

type MetricsState struct {
    TotalInferences     int64            `json:"total_inferences"`
    TotalErrors         int64            `json:"error_count"`
    LatencySumMs        float64          `json:"latency_sum_ms"`
    InferencesPerModel  map[string]int64 `json:"inferences_per_model"`
}

type Data struct {
    Users    []User         `json:"users"`
    Models   map[string]*Model `json:"models"`
    Webhooks []Webhook      `json:"webhooks"`
    Audit    []AuditEntry   `json:"audit"`
    Metrics  MetricsState   `json:"metrics"`
}

type Store struct {
    mu      sync.RWMutex
    data    *Data
    dataDir string
}

func NewID() string {
    b := make([]byte, 16)
    _, err := rand.Read(b)
    if err != nil {
        return time.Now().UTC().Format("20060102150405.000000")
    }
    return hex.EncodeToString(b)
}

func New(dataDir string) (*Store, error) {
    if err := os.MkdirAll(dataDir, 0755); err != nil {
        return nil, err
    }
    s := &Store{
        dataDir: dataDir,
        data: &Data{
            Models: make(map[string]*Model),
            Metrics: MetricsState{
                InferencesPerModel: make(map[string]int64),
            },
        },
    }
    if err := s.load(); err != nil {
        return nil, err
    }
    return s, nil
}

func (s *Store) WithLock(fn func(d *Data) error) error {
    s.mu.Lock()
    defer s.mu.Unlock()
    err := fn(s.data)
    if err != nil {
        return err
    }
    return s.saveLocked()
}

func (s *Store) WithRLock(fn func(d *Data) error) error {
    s.mu.RLock()
    defer s.mu.RUnlock()
    return fn(s.data)
}

func (s *Store) load() error {
    s.mu.Lock()
    defer s.mu.Unlock()

    if err := readJSON(filepath.Join(s.dataDir, "users.json"), &s.data.Users); err != nil {
        return err
    }
    if err := readJSON(filepath.Join(s.dataDir, "models.json"), &s.data.Models); err != nil {
        return err
    }
    if err := readJSON(filepath.Join(s.dataDir, "webhooks.json"), &s.data.Webhooks); err != nil {
        return err
    }
    if err := readJSON(filepath.Join(s.dataDir, "audit.json"), &s.data.Audit); err != nil {
        return err
    }
    if err := readJSON(filepath.Join(s.dataDir, "metrics.json"), &s.data.Metrics); err != nil {
        return err
    }

    if s.data.Models == nil {
        s.data.Models = make(map[string]*Model)
    }
    if s.data.Metrics.InferencesPerModel == nil {
        s.data.Metrics.InferencesPerModel = make(map[string]int64)
    }
    return nil
}

func (s *Store) saveLocked() error {
    if err := writeJSON(filepath.Join(s.dataDir, "users.json"), s.data.Users); err != nil {
        return err
    }
    if err := writeJSON(filepath.Join(s.dataDir, "models.json"), s.data.Models); err != nil {
        return err
    }
    if err := writeJSON(filepath.Join(s.dataDir, "webhooks.json"), s.data.Webhooks); err != nil {
        return err
    }
    if err := writeJSON(filepath.Join(s.dataDir, "audit.json"), s.data.Audit); err != nil {
        return err
    }
    return writeJSON(filepath.Join(s.dataDir, "metrics.json"), s.data.Metrics)
}

func readJSON(path string, v interface{}) error {
    data, err := os.ReadFile(path)
    if os.IsNotExist(err) {
        return nil
    }
    if err != nil {
        return err
    }
    if len(data) == 0 {
        return nil
    }
    return json.Unmarshal(data, v)
}

func writeJSON(path string, v interface{}) error {
    data, err := json.MarshalIndent(v, "", "  ")
    if err != nil {
        return err
    }
    if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
        return err
    }
    tmp := path + ".tmp"
    if err := os.WriteFile(tmp, data, 0644); err != nil {
        return err
    }
    return os.Rename(tmp, path)
}

func (s *Store) DataDir() string {
    return s.dataDir
}

var ErrNotFound = errors.New("not found")
EOF

