package auth

import (
    "crypto/rand"
    "crypto/sha256"
    "encoding/hex"
    "errors"
    "strings"
    "time"

    "mlgateway/internal/store"
)

const (
    RoleAdmin    = "admin"
    RoleDeployer = "deployer"
    RoleViewer   = "viewer"
)

var (
    ErrInvalidRole      = errors.New("invalid role")
    ErrUsernameExists   = errors.New("username already exists")
    ErrForbidden        = errors.New("forbidden")
    ErrInvalidCredentials = errors.New("invalid credentials")
)

type Service struct {
    store *store.Store
}

func New(s *store.Store) *Service {
    return &Service{store: s}
}

func validRole(role string) bool {
    return role == RoleAdmin || role == RoleDeployer || role == RoleViewer
}

func hashPassword(password string) (string, error) {
    salt := make([]byte, 16)
    if _, err := rand.Read(salt); err != nil {
        return "", err
    }
    h := sha256.Sum256(append(salt, []byte(password)...))
    return hex.EncodeToString(salt) + ":" + hex.EncodeToString(h[:]), nil
}

func verifyPassword(password, hash string) bool {
    parts := strings.SplitN(hash, ":", 2)
    if len(parts) != 2 {
        return false
    }
    h := sha256.Sum256(append([]byte(parts[0]), []byte(password)...))
    return hex.EncodeToString(h[:]) == parts[1]
}

func (s *Service) Register(username, password, role, callerRole string) (*store.User, error) {
    username = strings.TrimSpace(username)
    if username == "" || password == "" {
        return nil, errors.New("username and password are required")
    }
    if !validRole(role) {
        return nil, ErrInvalidRole
    }

    var created *store.User
    err := s.store.WithLock(func(d *store.Data) error {
        if len(d.Users) > 0 {
            if callerRole != RoleAdmin {
                return ErrForbidden
            }
            for _, u := range d.Users {
                if u.Username == username {
                    return ErrUsernameExists
                }
            }
        } else {
            role = RoleAdmin
        }

        hash, err := hashPassword(password)
        if err != nil {
            return err
        }

        user := store.User{
            ID:           store.NewID(),
            Username:     username,
            PasswordHash: hash,
            Role:         role,
            APIKey:       store.NewID(),
            CreatedAt:    time.Now().UTC(),
        }
        d.Users = append(d.Users, user)
        created = &d.Users[len(d.Users)-1]
        return nil
    })
    if err != nil {
        return nil, err
    }
    return created, nil
}

func (s *Service) Login(username, password string) (string, string, error) {
    var apiKey, role string
    err := s.store.WithRLock(func(d *store.Data) error {
        for _, u := range d.Users {
            if u.Username == username && verifyPassword(password, u.PasswordHash) {
                apiKey = u.APIKey
                role = u.Role
                return nil
            }
        }
        return ErrInvalidCredentials
    })
    if err != nil {
        return "", "", err
    }
    return apiKey, role, nil
}

func (s *Service) Authenticate(token string) (*store.User, bool) {
    if token == "" {
        return nil, false
    }
    var found *store.User
    _ = s.store.WithRLock(func(d *store.Data) error {
        for i := range d.Users {
            if d.Users[i].APIKey == token {
                found = &d.Users[i]
                return nil
            }
        }
        return nil
    })
    return found, found != nil
}

func CanAccess(role string, required string) bool {
    switch required {
    case RoleAdmin:
        return role == RoleAdmin
    case RoleDeployer:
        return role == RoleAdmin || role == RoleDeployer
    case RoleViewer:
        return role == RoleAdmin || role == RoleDeployer || role == RoleViewer
    default:
        return false
    }
}
EOF

