package registry

import (
    "encoding/json"
    "errors"
    "fmt"
    "io"
    "os"
    "path/filepath"
    "regexp"
    "strings"
    "time"

    "mlgateway/internal/store"
)

var (
    ErrNotFound      = errors.New("not found")
    ErrConflict      = errors.New("conflict")
    ErrValidation    = errors.New("validation error")
    ErrTooLarge      = errors.New("model binary too large")
)

var semverRe = regexp.MustCompile(`^[0-9]+\.[0-9]+\.[0-9]+$`)

type Service struct {
    store           *store.Store
    modelStorageDir string
    maxModelSize    int64
}

func New(s *store.Store, modelStorageDir string, maxModelSizeMB int) *Service {
    return &Service{
        store:           s,
        modelStorageDir: modelStorageDir,
        maxModelSize:    int64(maxModelSizeMB) * 1024 * 1024,
    }
}

func ValidateFramework(framework string) error {
    switch framework {
    case "tensorflow", "pytorch", "onnx", "custom":
        return nil
    default:
        return fmt.Errorf("%w: invalid framework %q", ErrValidation, framework)
    }
}

func ValidateSemver(version string) error {
    if !semverRe.MatchString(version) {
        return fmt.Errorf("%w: invalid semantic version %q", ErrValidation, version)
    }
    return nil
}

func ValidateSchema(schema json.RawMessage) error {
    if len(schema) == 0 || string(schema) == "null" {
        return fmt.Errorf("%w: schema is required", ErrValidation)
    }
    var obj map[string]interface{}
    if err := json.Unmarshal(schema, &obj); err != nil {
        return fmt.Errorf("%w: schema must be a JSON object", ErrValidation)
    }
    if obj == nil {
        return fmt.Errorf("%w: schema must be a JSON object", ErrValidation)
    }
    if t, ok := obj["type"]; ok {
        if _, ok := t.(string); !ok {
            return fmt.Errorf("%w: schema type must be a string", ErrValidation)
        }
    }
    if p, ok := obj["properties"]; ok {
        if _, ok := p.(map[string]interface{}); !ok {
            return fmt.Errorf("%w: schema properties must be an object", ErrValidation)
        }
    }
    if r, ok := obj["required"]; ok {
        if _, ok := r.([]interface{}); !ok {
            return fmt.Errorf("%w: schema required must be an array", ErrValidation)
        }
    }
    if i, ok := obj["items"]; ok {
        if _, ok := i.(map[string]interface{}); !ok {
            return fmt.Errorf("%w: schema items must be an object", ErrValidation)
        }
    }
    return nil
}

func (s *Service) Register(m *store.Model) (*store.Model, error) {
    m.Name = strings.TrimSpace(m.Name)
    m.Framework = strings.TrimSpace(m.Framework)
    m.Description = strings.TrimSpace(m.Description)
    m.Author = strings.TrimSpace(m.Author)

    if m.Name == "" {
        return nil, fmt.Errorf("%w: name is required", ErrValidation)
    }
    if err := ValidateFramework(m.Framework); err != nil {
        return nil, err
    }
    if err := ValidateSchema(m.InputSchema); err != nil {
        return nil, fmt.Errorf("input_schema: %w", err)
    }
    if err := ValidateSchema(m.OutputSchema); err != nil {
        return nil, fmt.Errorf("output_schema: %w", err)
    }
    if m.Labels == nil {
        m.Labels = map[string]string{}
    }

    var created *store.Model
    err := s.store.WithLock(func(d *store.Data) error {
        for _, existing := range d.Models {
            if existing.Name == m.Name {
                return fmt.Errorf("%w: model name already exists", ErrConflict)
            }
        }

        model := &store.Model{
            ID:           store.NewID(),
            Name:         m.Name,
            Framework:    m.Framework,
            Description: m.Description,
            Author:       m.Author,
            CreatedAt:    time.Now().UTC(),
            InputSchema:  m.InputSchema,
            OutputSchema: m.OutputSchema,
            Labels:       m.Labels,
            Lineage:      m.Lineage,
            Versions:     []*store.Version{},
        }
        d.Models[model.ID] = model
        created = model
        return nil
    })
    if err != nil {
        return nil, err
    }
    return created, nil
}

func (s *Service) List(name, framework, labelKey, labelValue string, deployedFilter *bool) []*store.Model {
    var result []*store.Model
    _ = s.store.WithRLock(func(d *store.Data) error {
        for _, m := range d.Models {
            if name != "" && !strings.Contains(strings.ToLower(m.Name), strings.ToLower(name)) {
                continue
            }
            if framework != "" && m.Framework != framework {
                continue
            }
            if labelKey != "" {
                v, ok := m.Labels[labelKey]
                if !ok || (labelValue != "" && v != labelValue) {
                    continue
                }
            }
            if deployedFilter != nil {
                hasDeployed := false
                for _, v := range m.Versions {
                    if v.Status == "deployed" {
                        hasDeployed = true
                        break
                    }
                }
                if *deployedFilter != hasDeployed {
                    continue
                }
            }
            result = append(result, m)
        }
        return nil
    })
    return result
}

func (s *Service) Get(id string) (*store.Model, error) {
    var model *store.Model
    err := s.store.WithRLock(func(d *store.Data) error {
        m, ok := d.Models[id]
        if !ok {
            return ErrNotFound
        }
        model = m
        return nil
    })
    if err != nil {
        return nil, err
    }
    return model, nil
}

func (s *Service) GetByName(name string) (*store.Model, error) {
    var model *store.Model
    err := s.store.WithRLock(func(d *store.Data) error {
        for _, m := range d.Models {
            if m.Name == name {
                model = m
                return nil
            }
        }
        return ErrNotFound
    })
    if err != nil {
        return nil, err
    }
    return model, nil
}

func (s *Service) Delete(id string) error {
    var paths []string
    err := s.store.WithLock(func(d *store.Data) error {
        m, ok := d.Models[id]
        if !ok {
            return ErrNotFound
        }
        for _, v := range m.Versions {
            if v.Status == "deployed" {
                return fmt.Errorf("%w: model has deployed version", ErrConflict)
            }
            if v.BinaryPath != "" {
                paths = append(paths, v.BinaryPath)
            }
        }
        delete(d.Models, id)
        return nil
    })
    if err != nil {
        return err
    }
    for _, p := range paths {
        _ = os.Remove(p)
    }
    return nil
}

func (s *Service) UploadVersion(id, version, releaseNotes string, reader io.Reader) (*store.Version, error) {
    if err := ValidateSemver(version); err != nil {
        return nil, err
    }

    dir := filepath.Join(s.modelStorageDir, id, version)
    if err := os.MkdirAll(dir, 0755); err != nil {
        return nil, err
    }
    binaryPath := filepath.Join(dir, "model.bin")
    tmpPath := binaryPath + ".tmp"
    f, err := os.Create(tmpPath)
    if err != nil {
        return nil, err
    }

    limited := io.LimitReader(reader, s.maxModelSize+1)
    n, err := io.Copy(f, limited)
    f.Close()
    if err != nil {
        _ = os.Remove(tmpPath)
        return nil, err
    }
    if n > s.maxModelSize {
        _ = os.Remove(tmpPath)
        return nil, ErrTooLarge
    }
    if err := os.Chmod(tmpPath, 0755); err != nil {
        _ = os.Remove(tmpPath)
        return nil, err
    }
    if err := os.Rename(tmpPath, binaryPath); err != nil {
        _ = os.Remove(tmpPath)
        return nil, err
    }

    var versionCreated *store.Version
    err = s.store.WithLock(func(d *store.Data) error {
        m, ok := d.Models[id]
        if !ok {
            return ErrNotFound
        }
        for _, v := range m.Versions {
            if v.Version == version {
                return fmt.Errorf("%w: version already exists", ErrConflict)
            }
        }
        v := &store.Version{
            Version:      version,
            ReleaseNotes: releaseNotes,
            BinaryPath:   binaryPath,
            Status:       "undeployed",
            CreatedAt:    time.Now().UTC(),
            Size:         n,
        }
        m.Versions = append(m.Versions, v)
        versionCreated = v
        return nil
    })
    if err != nil {
        _ = os.Remove(binaryPath)
        return nil, err
    }
    return versionCreated, nil
}

func (s *Service) ListVersions(id string) ([]*store.Version, error) {
    var versions []*store.Version
    err := s.store.WithRLock(func(d *store.Data) error {
        m, ok := d.Models[id]
        if !ok {
            return ErrNotFound
        }
        versions = m.Versions
        return nil
    })
    if err != nil {
        return nil, err
    }
    return versions, nil
}

func (s *Service) GetVersion(id, version string) (*store.Version, error) {
    var found *store.Version
    err := s.store.WithRLock(func(d *store.Data) error {
        m, ok := d.Models[id]
        if !ok {
            return ErrNotFound
        }
        for _, v := range m.Versions {
            if v.Version == version {
                found = v
                return nil
            }
        }
        return ErrNotFound
    })
    if err != nil {
        return nil, err
    }
    return found, nil
}

func (s *Service) DeployVersion(id, version string) (*store.Version, error) {
    var deployed *store.Version
    err := s.store.WithLock(func(d *store.Data) error {
        m, ok := d.Models[id]
        if !ok {
            return ErrNotFound
        }
        var target *store.Version
        for _, v := range m.Versions {
            if v.Version == version {
                target = v
                break
            }
        }
        if target == nil {
            return ErrNotFound
        }
        for _, v := range m.Versions {
            if v.Status == "deployed" {
                v.Status = "undeployed"
            }
        }
        target.Status = "deployed"
        deployed = target
        return nil
    })
    if err != nil {
        return nil, err
    }
    return deployed, nil
}

func (s *Service) UndeployVersion(id, version string) (*store.Version, error) {
    var undeployed *store.Version
    err := s.store.WithLock(func(d *store.Data) error {
        m, ok := d.Models[id]
        if !ok {
            return ErrNotFound
        }
        var target *store.Version
        for _, v := range m.Versions {
            if v.Version == version {
                target = v
                break
            }
        }
        if target == nil {
            return ErrNotFound
        }
        if target.Status == "deployed" {
            target.Status = "undeployed"
        }
        undeployed = target
        return nil
    })
    if err != nil {
        return nil, err
    }
    return undeployed, nil
}

func (s *Service) FindDeployedByName(name string) (*store.Model, *store.Version, error) {
    var model *store.Model
    var version *store.Version
    err := s.store.WithRLock(func(d *store.Data) error {
        for _, m := range d.Models {
            if m.Name == name {
                for _, v := range m.Versions {
                    if v.Status == "deployed" {
                        model = m
                        version = v
                        return nil
                    }
                }
            }
        }
        return ErrNotFound
    })
    if err != nil {
        return nil, nil, err
    }
    return model, version, nil
}
