        for _, m := range d.Models {
            for _, v := range m.Versions {
                if v.Status == "deployed" {
                    deployedModels++
                    break
                }
            }
        }
        totalInferences = d.Metrics.TotalInferences
        totalErrors = d.Metrics.TotalErrors
        latencySum = d.Metrics.LatencySumMs
        perModel = make(map[string]int64, len(d.Metrics.InferencesPerModel))
        for k, v := range d.Metrics.InferencesPerModel {
            perModel[k] = v
        }
        return nil
    })

    avg := 0.0
    if totalInferences > 0 {
        avg = latencySum / float64(totalInferences)
    }

    return map[string]interface{}{
