package inference

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os/exec"
	"time"

	"mlgateway/internal/metrics"
	"mlgateway/internal/registry"
	"mlgateway/internal/store"
)

type Service struct {
	registry   *registry.Service
	metrics   *metrics.Service
	timeout time.Duration
}

func New(r *registry.Service, m *metrics.Service, timeoutSec int) *Service {
	if timeoutSec <= 0 {
		timeoutSec = 30
	}
	return &Service{
		registry: r,
		metrics: m,
		timeout: time.Duration(timeoutSec) * time.Second,
	}
}

func (s *Service) Infer(modelName string, input json.RawMessage) (*store.Model, *store.Version, interface{}, error) {
	model, version, err := s.registry.FindDeployedByName(modelName)
	if err != nil {
		return nil, nil, nil, err
	}

	start := time.Now()
	result, runErr := s.runBinary(version.BinaryPath, input)
	latency := float64(time.Since(start).Milliseconds())

	if runErr != nil {
		s.metrics.RecordInference(modelName, latency, true)
		return model, version, nil, runErr
	}

	s.metrics.RecordInference(modelName, latency, false)
	return model, version, result, nil
}

func (s *Service) InferBatch(modelName string, inputs []json.RawMessage) (*store.Model, *store.Version, []interface{}, []string) {
	model, version, err := s.registry.FindDeployedByName(modelName)
	if err != nil {
		return nil, nil, nil, []string{err.Error()}
	}

	results := make([]interface{}, 0, len(inputs))
	var errs []string

	for _, input := range inputs {
		start := time.Now()
		result, runErr := s.runBinary(version.BinaryPath, input)
		latency := float64(time.Since(start).Milliseconds())

		if runErr != nil {
			s.metrics.RecordInference(modelName, latency, true)
			errs = append(errs, runErr.Error())
			results = append(results, nil)
		} else {
			s.metrics.RecordInference(modelName, latency, false)
			results = append(results, result)
		}
	}

	return model, version, results, errs
}

func (s *Service) runBinary(path string, input json.RawMessage) (interface{}, error) {
	ctx, cancel := context.WithTimeout(context.Background(), s.timeout)
	defer cancel()

	cmd := exec.CommandContext(ctx, path)
	cmd.Stdin = bytes.NewReader(input)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		if ctx.Err() == context.DeadlineExceeded {
			return nil, errors.New("inference timed out")
		}
		msg := stderr.String()
		if msg == "" {
			msg = err.Error()
		}
		return nil, fmt.Errorf("model execution failed: %s", msg)
	}

	var result interface{}
	if err := json.Unmarshal(stdout.Bytes(), &result); err != nil {
		return nil, fmt.Errorf("model returned invalid JSON: %w", err)
	}
	return result, nil
}
